        v = observation.get(key, default)
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            return v[0], v[1]
        return default

    def dist(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def step_toward(src, dst):
        return [clamp_step(dst[0] - src[0]), clamp_step(dst[1] - src[1])]

    def step_away(src, dst):
        return [clamp_step(src[0] - dst[0]), clamp_step(src[1] - dst[1])]

    def best_by_dist(items, src, fn=min):
        best_item = None
        best_score = None
        for item in items:
            if not isinstance(item, (list, tuple)) or len(item) < 2:
                continue
            p = (item[0], item[1])
            score = dist(src, p)
            if best_score is None or fn(score, best_score) == score:
                best_score = score
                best_item = p
        return best_item

    env = observation.get("environment_name", "resource_collection")
    sx_sy = get_pos("self_position", (0, 0))
    ox_sy = get_pos("opponent_position", None)
    sx, sy = sx_sy

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            if ox_sy is not None:
                return step_toward((sx, sy), ox_sy)
            return [0, 0]
        gw = observation.get("grid_width", 0) or 0
        gh = observation.get("grid_height", 0) or 0
        corners = [(0, 0), (0, gh - 1), (gw - 1, 0), (gw - 1, gh - 1)]
        if ox_sy is not None:
            target = max(corners, key=lambda c: dist(c, ox_sy))
            return step_toward((sx, sy), target)
        return [0, 0]

    if env == "territory_control":
        targets = observation.get("unclaimed_cells") or observation.get("opponent_territory") or observation.get("targets") or []
        if not targets:
            opp = observation.get("opponent_position")
            if isinstance(opp, (list, tuple)) and len(opp) >= 2:
                return step_away((sx, sy), (opp[0], opp[1]))
            return [0, 0]
        best = best_by_dist(targets, (sx, sy), min)
        if best is None:
            return [0, 0]
        return step_toward((sx, sy), best)

    resources = observation.get("resources") or observation.get("resource_positions") or observation.get("resource_cells") or []
    if resources:
        best = best_by_dist(resources, (sx, sy), min)
        if best is not None:
            return step_toward((sx, sy), best)

    # Fallback: avoid opponent if close, else hold
    if ox_sy is not None:
        return step_away((sx, sy), ox_sy)
    return [0, 0]

